    if (extensions["_risu_module_id"] !== args.env.id)
      continue;
    const storedHash = extensions["_risu_source_hash"];
    if (typeof storedHash !== "string")
      continue;
    const currentHash = targetBySourceHash.get(storedHash);
    if (!currentHash)
      continue;
