      deps.log.info(`event MESSAGE_SENT chatId=${chatId ?? "?"} characterId=${characterId ?? "?"} payload=${deps.dumpPayload(raw)}`);
      if (!chatId)
        return;
      deps.invalidateListenEditPreload(chatId);
      deps.refreshMessagesCache(chatId, userId);
